            aIngress = aIngress + (aOrbiterI ^ RotL64(aOrbiterB, 27U));
            aIngress = aIngress + (aOrbiterD ^ RotL64(aOrbiterF, 5U));
            aIngress = aIngress + RotL64(aOrbiterA, 47U);
            aIngress = TwistMix64::DiffuseA((aIngress + aScatter));
            //
            aWandererF = aWandererF + ((((RotL64(aScatter, 41U) + RotL64(aOrbiterE, 18U)) + aOrbiterI) + RotL64(aCarry, 41U)) + aWUSaltB[((aIndex + 382U)) & S_SALT1]);
            aWandererI = aWandererI ^ (((RotL64(aCross, 27U) + aOrbiterF) + RotL64(aOrbiterA, 35U)) + aWUSaltH[(((511U - aIndex) + 14U)) & S_SALT1]);
            aWandererC = aWandererC + (((RotL64(aPrevious, 5U) + RotL64(aOrbiterA, 41U)) + aOrbiterE) + RotL64(aCarry, 57U));
            aWandererA = aWandererA ^ ((RotL64(aIngress, 60U) + aOrbiterC) + RotL64(aOrbiterI, 29U));
            aWandererH = aWandererH + (((RotL64(aCross, 23U) + aOrbiterD) + RotL64(aOrbiterF, 11U)) + aWUSaltF[((aIndex + 337U)) & S_SALT1]);
            aWandererD = aWandererD ^ ((RotL64(aScatter, 11U) + RotL64(aOrbiterD, 57U)) + aOrbiterG);
            aWandererB = aWandererB + ((RotL64(aIngress, 53U) + RotL64(aOrbiterB, 3U)) + aOrbiterG);
            aWandererJ = aWandererJ ^ (((RotL64(aPrevious, 48U) + aOrbiterH) + RotL64(aOrbiterF, 22U)) + aWUSaltA[((aIndex + 44U)) & S_SALT1]);
            aWandererK = aWandererK + ((RotL64(aScatter, 35U) + RotL64(aOrbiterC, 47U)) + aOrbiterD);
