            //
            aOrbiterJ = ((aWandererJ + RotL64(aCross, 35U)) + RotL64(aCarry, 5U)) + 0x64C4B7630DF42EA8ULL;
            aOrbiterE = (aWandererK + RotL64(aIngress, 48U)) + 0xF965B169E9E9DEFAULL;
            aOrbiterB = ((aWandererG + RotL64(aPrevious, 27U)) + 0x34F62669CE5F8775ULL) + aOASaltG[(((511U - aIndex) + 195U)) & S_SALT1];
            aOrbiterA = ((aWandererE + RotL64(aScatter, 57U)) + 0x8A8D0FB99A268C59ULL) + aOASaltD[((aIndex + 53U)) & S_SALT1];
            aOrbiterK = ((aWandererA + RotL64(aCross, 39U)) + 0xA060EED8F4BBB69DULL) + aOASaltA[(((511U - aIndex) + 173U)) & S_SALT1];
            aOrbiterI = (aWandererC + RotL64(aIngress, 43U)) + 0x12AF3CC61EF51DD5ULL;
            aOrbiterG = ((aWandererH + RotL64(aPrevious, 10U)) + RotL64(aCarry, 43U)) + 0x10EAD97F5FA19A7CULL;
            aOrbiterF = (((aWandererI + RotL64(aScatter, 21U)) + RotL64(aCarry, 51U)) + 0x56743C260C160CCDULL) + aOASaltF[((aIndex + 99U)) & S_SALT1];
            aOrbiterD = ((aWandererD + RotL64(aPrevious, 3U)) + 0x9F9073ACAB88432AULL) + aOASaltH[(((511U - aIndex) + 102U)) & S_SALT1];
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterE) + 0x2FCF44A2A9D8FE84ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterJ) ^ 0x7DF2167018F5E473ULL;
            aOrbiterB = RotL64((aOrbiterB * 0xBC28422D59436D45ULL), 35U);
            //
            aOrbiterA = ((aOrbiterA + aOrbiterK) + 0xC8AE8329FD9CD2D4ULL) + aOUSaltC[((aIndex + 189U)) & S_SALT1];
            aOrbiterI = (aOrbiterI ^ aOrbiterA) ^ 0x2E512F186B011308ULL;
            aOrbiterI = RotL64((aOrbiterI * 0xBED9053B039174FBULL), 19U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterB) + 0x36289C8147F4F1E4ULL;
            aOrbiterG = ((aOrbiterG ^ aOrbiterK) ^ 0x045E96EE1909A3CEULL) ^ aOUSaltB[((aIndex + 287U)) & S_SALT1];
            aOrbiterG = RotL64((aOrbiterG * 0x3D40BE23B6A277DDULL), 29U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterA) + 0x37BD759B42E44982ULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterB) ^ 0x437B06AEF210EE09ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x911818AF191EA6BDULL), 41U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterJ) + 0x8F8A999EFA174F69ULL;
            aOrbiterK = ((aOrbiterK ^ aOrbiterD) ^ 0x6C169FC53D39B6E7ULL) ^ aOUSaltG[((aIndex + 240U)) & S_SALT1];
            aOrbiterK = RotL64((aOrbiterK * 0x224AB7156DA51779ULL), 13U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterD) + 0x2FC55E5E1C4157E9ULL;
            aOrbiterA = ((aOrbiterA ^ aOrbiterE) ^ 0x1DAD1625CA705CCBULL) ^ aOUSaltF[(((511U - aIndex) + 314U)) & S_SALT1];
            aOrbiterA = RotL64((aOrbiterA * 0x63514A8C539054DDULL), 5U);
            //
            aOrbiterF = ((aOrbiterF + aOrbiterI) + 0x2583BE40A11CB091ULL) + aOUSaltA[((aIndex + 471U)) & S_SALT1];
            aOrbiterE = (aOrbiterE ^ aOrbiterF) ^ 0x0CDC9A4C72855EB7ULL;
            aOrbiterE = RotL64((aOrbiterE * 0xE583F5C603DE8951ULL), 23U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterF) + 0x1271B6172C8ED1DFULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterG) ^ 0x0E9A88BCAB427C99ULL;
