            aOrbiterI = (((aWandererH + RotL64(aIngress, 43U)) + RotL64(aCarry, 27U)) + 0x56406BDBCE2D2DC5ULL) + aOASaltA[(((511U - aIndex) + 460U)) & S_SALT1];
            aOrbiterG = ((aWandererA + RotL64(aPrevious, 3U)) + 0x52DC1B690DA87C4EULL) + aOASaltC[((aIndex + 172U)) & S_SALT1];
            aOrbiterH = ((aWandererF + RotL64(aScatter, 53U)) + RotL64(aCarry, 43U)) + 0x9436D0E229D36747ULL;
            aOrbiterF = ((aWandererD + RotL64(aIngress, 36U)) + 0x3EE89B852042E24FULL) + aOASaltE[((aIndex + 451U)) & S_SALT1];
            //
            aOrbiterA = ((aOrbiterA + aOrbiterE) + 0xEA257A15B61E17ADULL) + aOUSaltA[(((511U - aIndex) + 346U)) & S_SALT1];
            aOrbiterD = (aOrbiterD ^ aOrbiterA) ^ 0x5FCC82C488F5AA81ULL;
            aOrbiterD = RotL64((aOrbiterD * 0xA8ADD655D226E93BULL), 29U);
            //
            aOrbiterE = ((aOrbiterE + aOrbiterI) + 0xCA1F37E73B9B55A3ULL) + aOUSaltE[((aIndex + 115U)) & S_SALT1];
            aOrbiterG = (aOrbiterG ^ aOrbiterE) ^ 0x36461D1ACAA2A8CAULL;
            aOrbiterG = RotL64((aOrbiterG * 0xFDF530E62A6BABE5ULL), 39U);
            //
            aOrbiterG = ((aOrbiterG + aOrbiterA) + 0xFBD137D0C7D6B7BAULL) + aOUSaltH[((aIndex + 89U)) & S_SALT1];
            aOrbiterH = ((aOrbiterH ^ aOrbiterG) ^ 0x89AFC7CAAC4A2DA5ULL) ^ aOUSaltD[(((511U - aIndex) + 233U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0x6D0429CEF6B15713ULL), 57U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterH) + 0x11C57691ECB670F1ULL;
