            aOrbiterI = RotL64((aOrbiterI * 0x45CCA2AED29A5357ULL), 13U);
            //
            aOrbiterI = ((aOrbiterI + aOrbiterF) + 0x52A1F6B67A4DCB74ULL) + aOUSaltC[(((511U - aIndex) + 246U)) & S_SALT1];
            aOrbiterA = (aOrbiterA ^ aOrbiterI) ^ 0x031AEBCD335F043EULL;
