            aScatter = TwistMix64::DiffuseA((aScatter ^ aTwistDomainWordScatter));
            //
            aOrbiterI = ((aWandererD + RotL64(aIngress, 43U)) + 0x823C932CCEEAAA71ULL) + aOASaltD[((aIndex + 489U)) & S_SALT1];
            aOrbiterD = (aWandererG + RotL64(aScatter, 35U)) + 0xA54FAF501AED447EULL;
            aOrbiterG = (aWandererE + RotL64(aPrevious, 4U)) + 0xD70C4D1A1A9BA342ULL;
