            //
            aOrbiterJ = (aWandererA + RotL64(aScatter, 11U)) + 0x554E4631834CE655ULL;
            aOrbiterE = ((aWandererF + RotL64(aPrevious, 23U)) + RotL64(aCarry, 51U)) + 0x32F8427BED9A735BULL;
            aOrbiterC = (aWandererJ + RotL64(aCross, 3U)) + 0x5F73EDDF3C2DE6D5ULL;
            aOrbiterI = (aWandererK + RotL64(aIngress, 57U)) + 0x7E8CD8325463A625ULL;
            aOrbiterA = ((aWandererB + RotL64(aCross, 52U)) + RotL64(aCarry, 39U)) + 0x8C33CCDDEE329D97ULL;
            aOrbiterH = (aWandererH + RotL64(aPrevious, 47U)) + 0xD08F0308F5FBD58FULL;
            aOrbiterK = ((aWandererG + RotL64(aScatter, 43U)) + 0x605B52212555DB1AULL) + aOASaltH[(((511U - aIndex) + 403U)) & S_SALT1];
            aOrbiterG = (((aWandererE + RotL64(aIngress, 19U)) + RotL64(aCarry, 5U)) + 0x3362A7DEBC4E4760ULL) + aOASaltA[(((511U - aIndex) + 243U)) & S_SALT1];
            aOrbiterB = ((aWandererI + RotL64(aCross, 30U)) + 0x19E5518EF32FA8A2ULL) + aOASaltE[(((511U - aIndex) + 266U)) & S_SALT1];
