            aOrbiterC = ((aOrbiterC ^ aOrbiterJ) ^ 0x472A72210DDCFC26ULL) ^ aOUSaltF[((aIndex + 175U)) & S_SALT1];
            aOrbiterC = RotL64((aOrbiterC * 0x6C3C697794416163ULL), 3U);
