            aOrbiterK = ((aWandererD + RotL64(aScatter, 53U)) + 0xEDD64838AD71983DULL) + aOASaltF[(((511U - aIndex) + 500U)) & S_SALT1];
            aOrbiterB = ((aWandererA + RotL64(aPrevious, 47U)) + 0xD0C520D945E30C97ULL) + aOASaltC[(((511U - aIndex) + 23U)) & S_SALT1];
