            aWandererH = aWandererH ^ ((RotL64(aScatter, 43U) + aOrbiterB) + RotL64(aOrbiterE, 22U));
            aWandererI = aWandererI + ((((RotL64(aCross, 29U) + aOrbiterC) + RotL64(aOrbiterJ, 37U)) + RotL64(aCarry, 43U)) + aWUSaltF[((aIndex + 97U)) & S_SALT1]);
            aWandererJ = aWandererJ ^ (((RotL64(aPrevious, 34U) + aOrbiterB) + RotL64(aOrbiterJ, 13U)) + aWUSaltA[(((511U - aIndex) + 199U)) & S_SALT1]);
            aWandererB = aWandererB + (((RotL64(aCross, 11U) + aOrbiterK) + RotL64(aOrbiterJ, 5U)) + aWUSaltG[(((511U - aIndex) + 349U)) & S_SALT1]);
            //
            aCarry = aCarry + (RotL64(aWandererB, 57U) ^ aWandererF);
