            aOrbiterE = ((aWandererA + RotL64(aIngress, 53U)) + 0x498D55B8A84D8D36ULL) + aOASaltD[(((511U - aIndex) + 75U)) & S_SALT1];
            aOrbiterI = (((aWandererI + RotL64(aScatter, 41U)) + RotL64(aCarry, 57U)) + 0x5A7B2689EDAFA98AULL) + aOASaltH[((aIndex + 53U)) & S_SALT1];
            aOrbiterD = (aWandererG + RotL64(aCross, 37U)) + 0x8653713573AF3121ULL;
