            aOrbiterB = ((aWandererF + RotL64(aIngress, 11U)) + RotL64(aCarry, 47U)) + 0xD4DD450E9E83B5BCULL;
            aOrbiterG = (aWandererH + RotL64(aPrevious, 6U)) + 0x5972B104421AF61BULL;
            //
            aOrbiterA = (aOrbiterA + aOrbiterH) + 0x2E7056C637D0338FULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterA) ^ 0x5E4B342C85C12A86ULL;
            aOrbiterK = RotL64((aOrbiterK * 0x08ED08A74159F62DULL), 19U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterI) + 0x1F1518C8C6A5DC71ULL;
            aOrbiterA = ((aOrbiterA ^ aOrbiterE) ^ 0x2F1A5873AB8F537DULL) ^ aOUSaltB[((aIndex + 235U)) & S_SALT1];
            aOrbiterA = RotL64((aOrbiterA * 0x8D32A973A21D6C2FULL), 21U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterJ) + 0x8082B184D0271776ULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterD) ^ 0x6C20A681D05BF3F6ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x9BE5B0C548F40C6BULL), 41U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterC) + 0x968107B4F82206A8ULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterK) ^ 0xE6077985C8B9751AULL;
            aOrbiterI = RotL64((aOrbiterI * 0xDA0E2DF1E6C96CCDULL), 39U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterA) + 0xD739F2D22223410EULL;
