            aWandererE = aWandererE + ((RotL64(aIngress, 43U) + RotL64(aOrbiterB, 37U)) + aOrbiterG);
            aWandererB = aWandererB ^ ((RotL64(aScatter, 41U) + RotL64(aOrbiterA, 5U)) + aOrbiterE);
            aWandererC = aWandererC + (((RotL64(aIngress, 22U) + RotL64(aOrbiterD, 12U)) + aOrbiterB) + aWUSaltD[((aIndex + 207U)) & S_SALT1]);
            aWandererI = aWandererI ^ ((RotL64(aCross, 37U) + RotL64(aOrbiterB, 29U)) + aOrbiterK);
            aWandererH = aWandererH + (((RotL64(aPrevious, 47U) + aOrbiterE) + RotL64(aOrbiterG, 21U)) + aWUSaltG[(((511U - aIndex) + 494U)) & S_SALT1]);
            aWandererK = aWandererK ^ ((RotL64(aCross, 29U) + RotL64(aOrbiterH, 35U)) + aOrbiterE);
            aWandererJ = aWandererJ + (((RotL64(aScatter, 13U) + RotL64(aOrbiterG, 3U)) + aOrbiterJ) + RotL64(aCarry, 23U));
            aWandererD = aWandererD ^ (((RotL64(aPrevious, 11U) + aOrbiterE) + RotL64(aOrbiterD, 47U)) + aWUSaltE[(((511U - aIndex) + 226U)) & S_SALT1]);
            //
