            //
            aOrbiterC = (aWandererG + RotL64(aCross, 29U)) + 0x8481CDD184424DEFULL;
            aOrbiterA = (((aWandererE + RotL64(aPrevious, 14U)) + RotL64(aCarry, 43U)) + 0x739F05C454837C57ULL) + aOASaltG[(((511U - aIndex) + 120U)) & S_SALT1];
            aOrbiterG = (aWandererD + RotL64(aIngress, 37U)) + 0xB147096C8984275DULL;
