            aOrbiterD = (aOrbiterD + aOrbiterH) + 0x69CA149E4E23193AULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterD) ^ 0xE2952A17ED151C14ULL;
            aOrbiterA = RotL64((aOrbiterA * 0xC38BE3AA48DC0C67ULL), 23U);
            //
            aOrbiterH = ((aOrbiterH + aOrbiterC) + 0xB463764E29508756ULL) + aOUSaltG[(((511U - aIndex) + 177U)) & S_SALT1];
            aOrbiterF = ((aOrbiterF ^ aOrbiterH) ^ 0xAC25F074F034AA24ULL) ^ aOUSaltE[(((511U - aIndex) + 88U)) & S_SALT1];
            aOrbiterF = RotL64((aOrbiterF * 0x0B6E1E3C0EBC9C81ULL), 39U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterG) + 0x378C668C3B6A4EF0ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterF) ^ 0xA28CCDBEC434252EULL;
            aOrbiterD = RotL64((aOrbiterD * 0x395456BC5A814789ULL), 57U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterK) + 0xB5679FA32F99CB05ULL;
